def clean_corpus(raw_text):
    clean_list = []

    for word in re.findall(r"\w+", raw_text):
        clean_list.append(word.lower())

    return clean_list


def generate_chain(word_map, start_word, length):
    if start_word is None:
        return []

    word_out = list(start_word)

    current_state = start_word
    while len(word_out) < length:
        if current_state in word_map and len(word_map[current_state]) != 0:
            next_word = random.choice(word_map[current_state])
            word_out.append(next_word)
            current_state = current_state[1:] + (next_word,)
        else:
            break

    result = " ".join(word_out)
    return result


def build_order_n_map(words, order):
    model = {}

    if order < 1 or len(words) <= order:
        return model

    for i in range(len(words) - order):
        state = tuple(words[i : i + order])
        next_word = words[i + order]
        model.setdefault(state, []).append(next_word)

    return model


training_data_list = clean_corpus(training_data)
word_map = build_order_n_map(training_data_list, 4)
print(generate_chain(word_map, next(iter(word_map), None), 12))
